<?php
declare(strict_types=1);
function ceH(mixed $s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function ceMoney(int $n):string{return number_format($n/100,2,',',' ').' Kč';}
function ceMinor(string $s):int{return clubAdminMinor($s);}
function ceValue(string $name,string $fallback=''):string{return staffListText($GLOBALS['ceValues']??[],$name)?:$fallback;}
function ceSelect(string $name,string $label,array $choices,bool $required=true,string $value=''):void {
    $value=ceValue($name,$value);?><label class="d-block mb-2"><?=ceH($label)?><select class="form-select" name="<?=ceH($name)?>" <?=$required?'required':''?>><option value=""><?=$required?'Vyberte z nabídky':'Bez vazby / není potřeba'?></option><?php foreach($choices as $r):?><option value="<?=ceH($r['id'])?>" <?=(string)$r['id']===$value?'selected':''?>><?=ceH($r['label'].' · #'.$r['id'])?></option><?php endforeach;?></select></label><?php
}
function ceStart(string $action):void {
    $GLOBALS['ceAction']=$action;$GLOBALS['ceValues']=$GLOBALS['ceDefaults'][$action]??[];
    if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&staffListText($_POST,'action')===$action)$GLOBALS['ceValues']=$_POST;
    ?><form method="post" class="border rounded p-3 mb-3"><input type="hidden" name="action" value="<?=ceH($action)?>"><input type="hidden" name="csrf_token" value="<?=ceH(csrf_token())?>"><input type="hidden" name="request_key" value="<?=ceH(ceValue('request_key',bin2hex(random_bytes(16))))?>"><?php
}
function ceInput(string $name,string $label,string $type='text',bool $required=true,string $value=''):void {
    $action=$GLOBALS['ceAction']??'';$map=['case_id'=>['case','Finanční případ'],'club_event_id'=>['club_event','Akce v kalendáři'],'legacy_event_id'=>['legacy_event','Původní provozní akce — připojit pouze podle doložené shody'],'leader_trainer_id'=>['trainer','Odpovědný vedoucí'],'previous_id'=>['claim','Předchozí verze — pouze pro opravu'],'receipt_id'=>['receipt','Účtenka / soukromá příloha'],'movement_id'=>['movement','Skutečný peněžní pohyb (datum, reference, částka)'],'advance_id'=>['advance','Záloha'],'to_advance_id'=>['advance','Cílová záloha'],'return_of_allocation_id'=>['allocation','Původní výplata při bankovním návratu'],'reverses_id'=>[$action==='consume'?'consumption':'allocation','Původní příděl / čerpání — pouze oprava']];
    if($name==='id')$map['id']=match($action){'claim_state'=>['claim','Konkrétní verze výdaje'],'advance_state','transfer'=>['advance','Záloha'],'close_case'=>['case','Finanční případ'],'consume'=>['claim_root','Výdaj k čerpání zálohy'],default=>['target','Výdaj nebo záloha k vypořádání']};
    if(isset($map[$name])){[$kind,$label]=$map[$name];ceSelect($kind==='target'?'target_ref':$name,$label,$GLOBALS['ceChoices'][$kind],$required,$value);return;}
    ?><label class="d-block mb-2"><?=ceH($label)?><input class="form-control" name="<?=ceH($name)?>" type="<?=ceH($type)?>" <?=$required?'required':''?> value="<?=ceH(ceValue($name,$value))?>"></label><?php
}
function ceEnd():void {ceInput('reason','Důvod zápisu (alespoň 10 znaků)');?><label class="d-block"><input type="checkbox" name="confirmed" value="1" required> Ověřil/a jsem podklady a potvrzuji tento zápis.</label><button class="btn btn-primary mt-2">Uložit</button></form><?php }
function cePerson(string $prefix):void {
    $choices=[];foreach(['trainer'=>'Pracovník','person'=>'Sportovec / člen'] as $kind=>$label)foreach($GLOBALS['ceChoices'][$kind] as $r)$choices[]=['id'=>$kind.':'.$r['id'],'label'=>$label.' · '.$r['label']];
    if($prefix!=='recipient')$choices[]=['id'=>'supplier','label'=>'Dodavatel — vyplňte označení níže'];
    $fallback=ceValue($prefix.'_kind')==='supplier'?'supplier':ceValue($prefix.'_kind').':'.ceValue($prefix.'_id');
    ceSelect($prefix.'_ref','Konkrétní osoba nebo dodavatel',$choices,true,$fallback);
    if($prefix!=='recipient')ceInput($prefix.'_label','Označení dodavatele (u vybrané osoby se jméno načte z evidence)','text',false);
}
function ceLines():void {
    $lines=$GLOBALS['ceValues']['lines']??[['amount'=>'','accepted'=>'1','case_id'=>ceValue('case_id'),'activity'=>'','purpose'=>'']];
    if(!is_array($lines))$lines=[];
    ?><h3 class="h5">Položky dokladu</h3><p>Uveďte celý doklad včetně neuznané části. Součet musí odpovídat celkové částce.</p><div class="table-responsive"><table class="table" id="expense-lines"><thead><tr><th>Částka Kč</th><th>Uznání</th><th>Finanční případ</th><th>Činnost</th><th>Účel</th><th></th></tr></thead><tbody><?php foreach($lines as $i=>$line)ceLineRow((string)$i,(array)$line);?></tbody></table></div><button type="button" class="btn btn-outline-secondary mb-3" id="add-expense-line">Přidat položku</button><template id="expense-line-template"><?php ceLineRow('__INDEX__',['case_id'=>ceValue('case_id')]);?></template><?php
}
function ceLineRow(string $i,array $line):void { $prefix='lines['.$i.']';?><tr><?php foreach(['amount','accepted','case_id','activity','purpose'] as $field):?><td><?php if(in_array($field,['accepted','case_id'],true)):?><select aria-label="<?=ceH($field==='accepted'?'Uznání položky':'Případ položky')?>" class="form-select" name="<?=ceH($prefix.'['.$field.']')?>"><?php $options=$field==='accepted'?[['id'=>'1','label'=>'Uznaná část'],['id'=>'0','label'=>'Neuznaná část']]:array_merge([['id'=>'','label'=>'Bez případu']],$GLOBALS['ceChoices']['case']);foreach($options as $o):?><option value="<?=ceH($o['id'])?>" <?=(string)($line[$field]??'')===(string)$o['id']?'selected':''?>><?=ceH($o['label'])?></option><?php endforeach;?></select><?php else:?><input aria-label="<?=ceH(['amount'=>'Částka položky Kč','activity'=>'Činnost položky','purpose'=>'Účel položky'][$field])?>" class="form-control" name="<?=ceH($prefix.'['.$field.']')?>" value="<?=ceH($line[$field]??'')?>"><?php endif;?></td><?php endforeach;?><td><?php if(!empty($line['stock_movement_id'])):?><input type="hidden" name="<?=ceH($prefix.'[stock_movement_id]')?>" value="<?=(int)$line['stock_movement_id']?>"><small>Původní skladová vazba #<?=(int)$line['stock_movement_id']?></small><?php endif;?><button type="button" class="btn btn-sm btn-outline-secondary" data-remove-line>Odebrat</button></td></tr><?php }

function ceCaseView(array $data):void {
    $c=$data['case'];?><section class="card card-body mb-4" id="case-detail"><h2><?=ceH($c['title'])?> — vyúčtování</h2><p>Termín <?=ceH($c['due_on'])?> · <?=ceH($c['state'])?> · <?=ceH($c['evidence'])?></p>
    <?php if($c['club_event_id']):?><p><a href="club_event_work_admin.php?event_id=<?=(int)$c['club_event_id']?>">Zajištění a účast na akci</a></p><?php endif;?>
    <?php if($c['legacy_event_id']):?><p><a href="udalosti/vyuctovat.php?id=<?=(int)$c['legacy_event_id']?>">Původní provozní podklady a účtenky</a> · Uzavření propojeného případu vyřizujte zde ve Výdajích a zálohách.</p><?php endif;?>
    <p><a href="#claim-form">Zapsat výdaj</a> · <a href="#advance-form">Požádat o zálohu</a> · <a href="uctenky/formular.php?expense_case_id=<?=(int)$c['id']?>">Připojit novou účtenku / přílohu</a></p>
    <h3 class="h5">Co zbývá před uzavřením</h3><?php if($data['blockers']):?><ul><?php foreach($data['blockers'] as $b):?><li><?=ceH($b)?></li><?php endforeach;?></ul><?php else:?><p>V aktuálních výdajích a zálohách nebyla nalezena překážka. Konečnou kontrolu provede samostatné potvrzení uzavření případu.</p><?php endif;?>
    <h3 class="h5">Doklady a opravné verze</h3><ul><?php foreach($data['claims'] as $r):?><li><a href="?case_id=<?=(int)$c['id']?>&amp;claim_id=<?=(int)$r['id']?>#claim-detail"><?=ceH($r['supplier'].' '.$r['document_number'].' · v'.$r['version_no'].' · '.$r['state'])?></a> · <?=ceH(ceMoney($r['balance']['remaining_minor']))?> zbývá za celý závazek</li><?php endforeach;?></ul>
    <?php foreach($data['receipts'] as $r):?><p>Účtenka k doložení: <a href="?case_id=<?=(int)$c['id']?>&amp;receipt_id=<?=(int)$r['id']?>#claim-form"><?=ceH($r['datum'].' '.$r['poznamka'])?></a></p><?php endforeach;?>
    <h3 class="h5">Zálohy</h3><ul><?php foreach($data['advances'] as $a):?><li><a href="?case_id=<?=(int)$c['id']?>&amp;advance_id=<?=(int)$a['id']?>#advance-detail"><?=ceH($a['recipient_label'].' · '.$a['purpose'])?></a> · <?=ceH(ceMoney($a['balance']['balance_minor']))?> saldo · <?=ceH($a['state'])?></li><?php endforeach;?></ul>
    <details><summary>Historie vyřízení případu</summary><?php foreach($data['history'] as $h):?><p><?=ceH($h['created_at'].' · '.$h['jmeno'].' · '.$h['entity_type'].' #'.$h['entity_id'].' · '.$h['event_type'].' · '.$h['reason'])?></p><?php endforeach;?></details></section><?php
}
function ceClaimView(PDO $pdo,array $claim):void {
    $b=clubExpenseClaimBalance($pdo,(int)$claim['root_id']);?><section id="claim-detail" class="card card-body mb-4"><h2><?=ceH($claim['supplier'].' '.$claim['document_number'])?> — verze <?=(int)$claim['version_no']?></h2><p><?=ceH($claim['creditor_label'].' · '.$claim['state'].' · '.$claim['purpose'])?></p><p>Doklad <?=ceH(ceMoney((int)$claim['amount_minor']))?> · uznáno v této verzi <?=ceH(ceMoney((int)$claim['accepted_minor']))?> · zbývá za závazek <?=ceH(ceMoney($b['remaining_minor']))?></p><p><?=ceH($claim['document_evidence'])?></p><?php if($claim['receipt_id']):?><p><a href="private_download.php?kind=receipt&amp;id=<?=(int)$claim['receipt_id']?>">Soukromá příloha účtenky</a></p><?php endif;?>
    <table class="table"><tr><th>Položka</th><th>Uznání</th><th>Částka</th></tr><?php foreach(json_decode($claim['items_json'],true) as $line):?><tr><td><?=ceH($line['activity'].' · '.$line['purpose'])?></td><td><?=$line['accepted']?'Uznáno':'Neuznáno'?></td><td><?=ceH(ceMoney((int)$line['amount_minor']))?></td></tr><?php endforeach;?></table>
    <p><a href="#claim-state">Předložit / rozhodnout o této verzi</a> · <a href="?<?=ceH(http_build_query(['case_id'=>$claim['case_id'],'claim_id'=>$claim['id'],'correct'=>1]))?>#claim-form">Připravit opravnou verzi</a> · <a href="#allocation-form">Vypořádání</a></p>
    <?php ceSettlementView($pdo,'claim',(int)$claim['root_id']);$q=$pdo->prepare('SELECT c.id,c.version_no,c.state,e.created_at,e.event_type,e.reason,t.jmeno FROM club_expense_claims c LEFT JOIN club_expense_events e ON e.entity_type=\'claim\' AND e.entity_id=c.id LEFT JOIN treneri t ON t.id=e.actor_trainer_id WHERE c.root_id=? ORDER BY c.version_no,e.id');$q->execute([$claim['root_id']]);?><details><summary>Historie závazku</summary><?php foreach($q->fetchAll(PDO::FETCH_ASSOC) as $h):?><p><a href="?claim_id=<?=(int)$h['id']?>#claim-detail">Verze <?=(int)$h['version_no']?></a> <?=ceH($h['state'].' · '.$h['created_at'].' · '.$h['jmeno'].' · '.$h['event_type'].' · '.$h['reason'])?></p><?php endforeach;?></details></section><?php
}
function ceSettlementView(PDO $pdo,string $kind,int $id):void {
    $types=$kind==='claim'?"'expense_claim','expense_claim_return'":"'expense_advance_out','expense_advance_in'";
    $q=$pdo->prepare("SELECT a.id,a.case_type,a.effective_on,a.amount_minor,m.source_reference FROM accounting_allocations a JOIN accounting_movements m ON m.id=a.movement_id WHERE a.case_id=? AND a.case_type IN ($types) ORDER BY a.id");$q->execute([$id]);
    ?><details><summary>Doložené pohyby a čerpání</summary><p>Záporný příděl je oprava přiřazení, nikoli skutečná vratka peněz.</p><ul><?php foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r):?><li><?=ceH('#'.$r['id'].' · '.$r['case_type'].' · '.$r['effective_on'].' · '.$r['source_reference'].' · '.ceMoney((int)$r['amount_minor']))?></li><?php endforeach;?>
    <?php $q=$pdo->prepare('SELECT * FROM club_expense_consumptions WHERE '.($kind==='claim'?'claim_root_id':'advance_id').'=? ORDER BY id');$q->execute([$id]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r):?><li>Čerpání #<?=(int)$r['id']?> · <?=ceH($r['effective_on'].' · '.ceMoney((int)$r['amount_minor']).' · '.$r['reason'])?></li><?php endforeach;?></ul></details><?php
}
function ceAdvanceView(PDO $pdo,array $a):void {
    $b=clubExpenseAdvanceBalance($pdo,(int)$a['id']);?><section id="advance-detail" class="card card-body mb-4"><h2>Záloha <?=ceH($a['recipient_label'])?></h2><p><?=ceH($a['purpose'].' · '.$a['state'])?> · předáno <?=ceH(ceMoney($b['out_minor']))?> · vráceno <?=ceH(ceMoney($b['returned_minor']))?> · čerpáno <?=ceH(ceMoney($b['consumed_minor']))?> · převody <?=ceH(ceMoney($b['transferred_minor']))?> · saldo <?=ceH(ceMoney($b['balance_minor']))?></p><p><a href="#advance-state">Schválení / uzavření</a> · <a href="#allocation-form">Doložit předání nebo vratku</a></p><?php ceSettlementView($pdo,'advance',(int)$a['id']);
    $q=$pdo->prepare("SELECT e.*,t.jmeno FROM club_expense_events e LEFT JOIN treneri t ON t.id=e.actor_trainer_id WHERE e.entity_type='advance' AND e.entity_id=? ORDER BY e.id");$q->execute([$a['id']]);?><details><summary>Historie zálohy</summary><?php foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r):?><p><?=ceH($r['created_at'].' · '.$r['jmeno'].' · '.$r['event_type'].' · '.$r['reason'])?></p><?php endforeach;?>
    <?php $q=$pdo->prepare('SELECT * FROM club_expense_transfers WHERE from_advance_id=? OR to_advance_id=? ORDER BY id');$q->execute([$a['id'],$a['id']]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r):?><p>Předání mezi zálohami #<?=(int)$r['from_advance_id']?> → #<?=(int)$r['to_advance_id']?> · <?=ceH($r['effective_on'].' · '.ceMoney((int)$r['amount_minor']).' · '.$r['evidence'].' · '.$r['reason'])?></p><?php endforeach;?></details></section><?php
}
